import { useState } from "react";

// ── Shared design tokens ──────────────────────────────────────────
const TOKEN = {
  black:    "#0a0a0a",
  white:    "#fafaf8",
  gold:     "#c9a84c",
  goldDark: "#8a6f2e",
  goldLight:"#e8d5a3",
  gray100:  "#f0ede8",
  gray200:  "#e0dbd2",
  gray400:  "#9b9690",
  gray600:  "#5a5650",
  red:      "#c0392b",
  green:    "#27ae60",
  fontDisplay: "'Playfair Display', Georgia, serif",
  fontBody:    "'DM Sans', 'Segoe UI', sans-serif",
  fontMono:    "'DM Mono', 'Courier New', monospace",
};

// ── Base styles ──────────────────────────────────────────────────
const S = {
  page: {
    minHeight: "100vh",
    display: "flex",
    fontFamily: TOKEN.fontBody,
    background: TOKEN.white,
  },
  left: {
    flex: 1,
    background: TOKEN.black,
    display: "flex",
    flexDirection: "column",
    justifyContent: "space-between",
    padding: "48px",
    position: "relative",
    overflow: "hidden",
  },
  leftGlow: {
    position: "absolute", inset: 0,
    background: "radial-gradient(ellipse at 20% 80%,rgba(201,168,76,.20) 0%,transparent 55%),radial-gradient(ellipse at 80% 20%,rgba(201,168,76,.10) 0%,transparent 50%)",
    pointerEvents: "none",
  },
  leftInner: { position: "relative", zIndex: 1 },
  logo: {
    fontFamily: TOKEN.fontDisplay, fontSize: "28px", fontWeight: 900,
    color: "#fff", textDecoration: "none", display: "block", marginBottom: "60px",
  },
  tagline: {
    fontFamily: TOKEN.fontDisplay, fontSize: "clamp(26px,3.2vw,46px)",
    fontWeight: 700, color: "#fff", lineHeight: 1.1, marginBottom: "14px",
  },
  taglineSub: { fontSize: "15px", color: "rgba(255,255,255,.5)", lineHeight: 1.65, maxWidth: "360px", marginBottom: "44px" },
  features: { display: "flex", flexDirection: "column", gap: "14px" },
  feat: { display: "flex", alignItems: "center", gap: "12px", fontSize: "14px", color: "rgba(255,255,255,.7)" },
  featIcon: {
    width: "36px", height: "36px", borderRadius: "50%",
    background: "rgba(201,168,76,.15)", border: "1px solid rgba(201,168,76,.3)",
    display: "flex", alignItems: "center", justifyContent: "center", fontSize: "16px", flexShrink: 0,
  },
  leftFoot: { position: "relative", zIndex: 1, fontSize: "13px", color: "rgba(255,255,255,.25)" },

  right: {
    width: "540px",
    background: TOKEN.white,
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    padding: "40px 40px",
    overflowY: "auto",
  },
  box: { width: "100%", maxWidth: "420px" },

  tabs: {
    display: "flex", border: "1.5px solid #e0dbd2",
    borderRadius: "8px", overflow: "hidden", marginBottom: "32px",
  },
  tab: {
    flex: 1, padding: "12px", textAlign: "center", fontSize: "15px",
    fontWeight: 500, cursor: "pointer", border: "none",
    background: "transparent", color: TOKEN.gray400, fontFamily: TOKEN.fontBody,
  },
  tabActive: {
    flex: 1, padding: "12px", textAlign: "center", fontSize: "15px",
    fontWeight: 600, cursor: "pointer", border: "none",
    background: TOKEN.black, color: "#fff", fontFamily: TOKEN.fontBody,
  },

  title: { fontFamily: TOKEN.fontDisplay, fontSize: "26px", fontWeight: 700, marginBottom: "5px" },
  subtitle: { fontSize: "14px", color: TOKEN.gray400, marginBottom: "24px" },

  /* Step indicator */
  stepRow: { display: "flex", alignItems: "center", marginBottom: "28px" },
  stepNum: (state) => ({
    width: "30px", height: "30px", borderRadius: "50%",
    display: "flex", alignItems: "center", justifyContent: "center",
    fontSize: "13px", fontWeight: 700, flexShrink: 0,
    background: state === "done" ? TOKEN.green : state === "active" ? TOKEN.black : TOKEN.gray100,
    color: state === "pending" ? TOKEN.gray400 : "#fff",
    transition: "all .3s",
  }),
  stepLabel: (state) => ({
    fontSize: "12px", marginTop: "4px", textAlign: "center",
    color: state === "active" ? TOKEN.black : TOKEN.gray400,
    fontWeight: state === "active" ? 600 : 400,
  }),
  stepLine: { flex: 1, height: "1px", background: TOKEN.gray200, margin: "0 8px" },

  group: { marginBottom: "16px" },
  label: { display: "block", fontSize: "13px", fontWeight: 500, color: TOKEN.gray600, marginBottom: "6px" },
  req: { color: TOKEN.red, marginLeft: "2px" },
  input: {
    width: "100%", height: "48px", padding: "0 16px",
    border: "1.5px solid #e0dbd2", borderRadius: "8px",
    fontFamily: TOKEN.fontBody, fontSize: "14px",
    color: TOKEN.black, background: TOKEN.white,
    outline: "none", boxSizing: "border-box", transition: "border-color .2s, box-shadow .2s",
  },
  inputFocused: { borderColor: TOKEN.gold, boxShadow: "0 0 0 4px rgba(201,168,76,.12)" },
  inputError: { borderColor: TOKEN.red, boxShadow: "0 0 0 4px rgba(192,57,43,.1)" },
  hint: { fontSize: "12px", color: TOKEN.gray400, marginTop: "5px" },
  errMsg: { fontSize: "12px", color: TOKEN.red, marginTop: "5px" },
  inputWrap: { position: "relative" },
  eyeBtn: {
    position: "absolute", right: "14px", top: "50%",
    transform: "translateY(-50%)", background: "none",
    border: "none", cursor: "pointer", fontSize: "17px", color: TOKEN.gray400, padding: 0,
  },
  formRow2: { display: "grid", gridTemplateColumns: "1fr 1fr", gap: "14px" },
  phoneWrap: {
    display: "flex", border: "1.5px solid #e0dbd2", borderRadius: "8px",
    overflow: "hidden", transition: "border-color .2s, box-shadow .2s",
  },
  phoneFlag: {
    height: "48px", padding: "0 12px",
    background: TOKEN.gray100, border: "none",
    borderRight: "1.5px solid #e0dbd2",
    fontSize: "14px", fontFamily: TOKEN.fontBody, cursor: "pointer",
    display: "flex", alignItems: "center", gap: "6px", flexShrink: 0, whiteSpace: "nowrap",
  },
  phoneNum: {
    flex: 1, height: "48px", padding: "0 14px",
    border: "none", fontFamily: TOKEN.fontBody, fontSize: "14px",
    outline: "none", background: "transparent", color: TOKEN.black,
  },

  /* Password strength */
  strengthBar: { display: "flex", gap: "4px", marginTop: "8px" },
  strengthSeg: (active, color) => ({
    flex: 1, height: "3px", borderRadius: "2px",
    background: active ? color : TOKEN.gray200, transition: "background .3s",
  }),
  strengthLabel: (color) => ({ fontSize: "11px", color, marginTop: "3px", fontWeight: 500 }),

  /* Terms checkbox */
  termsRow: { display: "flex", alignItems: "flex-start", gap: "10px", marginBottom: "20px" },
  termsLabel: { fontSize: "13px", color: TOKEN.gray600, lineHeight: 1.5 },
  termsLink: { color: TOKEN.gold, textDecoration: "none" },

  submitBtn: {
    width: "100%", height: "52px", background: TOKEN.black, color: "#fff",
    border: "none", borderRadius: "8px", fontFamily: TOKEN.fontBody,
    fontSize: "15px", fontWeight: 600, cursor: "pointer",
    display: "flex", alignItems: "center", justifyContent: "center", gap: "8px",
    transition: "all .25s",
  },

  /* Social */
  divider: { display: "flex", alignItems: "center", gap: "12px", color: TOKEN.gray400, fontSize: "13px", margin: "20px 0" },
  divLine: { flex: 1, height: "1px", background: TOKEN.gray200 },
  social: { display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px" },
  socialBtn: {
    height: "48px", border: "1.5px solid #e0dbd2",
    borderRadius: "8px", background: "#fff",
    cursor: "pointer", fontFamily: TOKEN.fontBody,
    fontSize: "14px", fontWeight: 500, color: TOKEN.black,
    display: "flex", alignItems: "center", justifyContent: "center", gap: "8px",
  },
  footerTxt: { textAlign: "center", marginTop: "20px", fontSize: "14px", color: TOKEN.gray400 },
  footerLink: { color: TOKEN.gold, textDecoration: "none", fontWeight: 500 },

  /* OTP */
  otpRow: { display: "flex", gap: "10px", justifyContent: "center", margin: "24px 0" },
  otpDigit: (filled) => ({
    width: "52px", height: "56px", textAlign: "center",
    fontFamily: TOKEN.fontMono, fontSize: "22px", fontWeight: 600,
    border: `2px solid ${filled ? TOKEN.gold : TOKEN.gray200}`,
    borderRadius: "8px", outline: "none", background: TOKEN.white,
    boxShadow: filled ? "0 0 0 3px rgba(201,168,76,.15)" : "none",
    transition: "border-color .2s, box-shadow .2s",
  }),
  resend: { textAlign: "center", fontSize: "13px", color: TOKEN.gray400, marginTop: "12px" },
  resendLink: { color: TOKEN.gold, cursor: "pointer", fontWeight: 500 },
  backBtn: {
    background: "none", border: "none", color: TOKEN.gold,
    fontSize: "13px", fontWeight: 500, cursor: "pointer",
    display: "flex", alignItems: "center", gap: "4px",
    padding: 0, marginBottom: "18px", fontFamily: TOKEN.fontBody,
  },

  /* Success */
  successWrap: { textAlign: "center", padding: "32px 0" },
  successIcon: { fontSize: "72px", marginBottom: "18px" },
  successTitle: { fontFamily: TOKEN.fontDisplay, fontSize: "26px", fontWeight: 700, marginBottom: "10px" },
  successDesc: { fontSize: "15px", color: TOKEN.gray400, marginBottom: "28px" },
  successBtn: {
    display: "inline-flex", alignItems: "center", gap: "8px",
    padding: "14px 40px", background: TOKEN.black, color: "#fff",
    borderRadius: "100px", textDecoration: "none",
    fontFamily: TOKEN.fontBody, fontSize: "15px", fontWeight: 600,
  },

  /* Alert */
  alert: (type) => ({
    padding: "12px 14px", borderRadius: "8px", fontSize: "13px",
    marginBottom: "14px", display: "flex", alignItems: "center", gap: "8px",
    background: type === "error" ? "#fee2e2" : "#dcfce7",
    color: type === "error" ? "#991b1b" : "#166534",
    border: `1px solid ${type === "error" ? "#fca5a5" : "#86efac"}`,
  }),
};

// ── Password strength checker ────────────────────────────────────
function getStrength(pw) {
  if (!pw) return { score: 0, label: "", color: "" };
  let score = 0;
  if (pw.length >= 8)  score++;
  if (/[A-Z]/.test(pw)) score++;
  if (/[0-9]/.test(pw)) score++;
  if (/[^A-Za-z0-9]/.test(pw)) score++;
  const map = [
    { label: "", color: "" },
    { label: "Weak", color: "#c0392b" },
    { label: "Fair", color: "#e67e22" },
    { label: "Good", color: "#f39c12" },
    { label: "Strong", color: "#27ae60" },
  ];
  return { score, ...map[score] };
}

// ── OTP Component ────────────────────────────────────────────────
function OTPInput({ id, value, onChange }) {
  const digits = value.split("").concat(Array(6).fill("")).slice(0, 6);
  const upd = (e, i) => {
    const v = e.target.value.replace(/\D/g, "").slice(0, 1);
    const n = [...digits]; n[i] = v;
    onChange(n.join(""));
    if (v && i < 5) document.getElementById(`${id}-${i + 1}`)?.focus();
  };
  const kd = (e, i) => {
    if (e.key === "Backspace" && !digits[i] && i > 0) document.getElementById(`${id}-${i - 1}`)?.focus();
  };
  const paste = (e) => {
    e.preventDefault();
    const t = e.clipboardData.getData("text").replace(/\D/g, "").slice(0, 6);
    onChange(t.padEnd(6, ""));
    document.getElementById(`${id}-${Math.min(t.length, 5)}`)?.focus();
  };
  return (
    <div style={S.otpRow}>
      {digits.map((d, i) => (
        <input key={i} id={`${id}-${i}`} type="text" inputMode="numeric"
          maxLength={1} value={d}
          style={S.otpDigit(!!d)}
          onChange={(e) => upd(e, i)}
          onKeyDown={(e) => kd(e, i)}
          onPaste={paste}
        />
      ))}
    </div>
  );
}

// ── Input with focus highlight ───────────────────────────────────
function FInput({ label, required, type = "text", placeholder, value, onChange, hint, error, rightSlot, autoComplete }) {
  const [focused, setFocused] = useState(false);
  return (
    <div style={S.group}>
      {label && <label style={S.label}>{label}{required && <span style={S.req}>*</span>}</label>}
      <div style={S.inputWrap}>
        <input
          type={type}
          placeholder={placeholder}
          value={value}
          autoComplete={autoComplete}
          onChange={(e) => onChange(e.target.value)}
          onFocus={() => setFocused(true)}
          onBlur={() => setFocused(false)}
          style={{
            ...S.input,
            paddingRight: rightSlot ? "48px" : "16px",
            ...(error ? S.inputError : focused ? S.inputFocused : {}),
          }}
        />
        {rightSlot}
      </div>
      {hint && !error && <p style={S.hint}>{hint}</p>}
      {error && <p style={S.errMsg}>⚠ {error}</p>}
    </div>
  );
}

// ── PhoneInput ────────────────────────────────────────────────────
function PhoneInput({ value, onChange, error }) {
  const [focused, setFocused] = useState(false);
  return (
    <div style={S.group}>
      <label style={S.label}>Phone Number<span style={S.req}>*</span></label>
      <div style={{
        ...S.phoneWrap,
        ...(error ? { borderColor: TOKEN.red } : focused ? { borderColor: TOKEN.gold, boxShadow: "0 0 0 4px rgba(201,168,76,.12)" } : {}),
      }}>
        <div style={S.phoneFlag}>🇮🇳 +91</div>
        <input
          type="tel" placeholder="98765 43210"
          value={value} maxLength={10}
          onChange={(e) => onChange(e.target.value.replace(/\D/g, "").slice(0, 10))}
          onFocus={() => setFocused(true)}
          onBlur={() => setFocused(false)}
          style={S.phoneNum}
        />
      </div>
      {error && <p style={S.errMsg}>⚠ {error}</p>}
    </div>
  );
}

// ── Main Register Component ──────────────────────────────────────
export default function Register() {
  const [step, setStep] = useState(1); // 1=details, 2=verify, 3=done

  // Form fields
  const [firstName, setFirstName] = useState("");
  const [lastName,  setLastName]  = useState("");
  const [email,     setEmail]     = useState("");
  const [phone,     setPhone]     = useState("");
  const [password,  setPassword]  = useState("");
  const [confirm,   setConfirm]   = useState("");
  const [terms,     setTerms]     = useState(false);
  const [showPw,    setShowPw]    = useState(false);
  const [showCpw,   setShowCpw]   = useState(false);
  const [errors,    setErrors]    = useState({});
  const [loading,   setLoading]   = useState(false);
  const [alert,     setAlert]     = useState(null); // {type, msg}

  // OTP
  const [otp,       setOtp]       = useState("");
  const [otpTimer,  setOtpTimer]  = useState(0);

  const strength = getStrength(password);

  const startTimer = () => {
    setOtpTimer(30);
    const iv = setInterval(() => setOtpTimer(t => { if (t <= 1) { clearInterval(iv); return 0; } return t - 1; }), 1000);
  };

  // ── Validation ──
  const validate = () => {
    const e = {};
    if (!firstName.trim()) e.firstName = "First name is required";
    if (!lastName.trim())  e.lastName  = "Last name is required";
    if (!email.trim() || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) e.email = "Valid email is required";
    if (phone.length !== 10) e.phone = "Enter valid 10-digit phone number";
    if (password.length < 8) e.password = "Password must be at least 8 characters";
    if (password !== confirm) e.confirm = "Passwords do not match";
    if (!terms) e.terms = "Please accept the terms to continue";
    setErrors(e);
    return Object.keys(e).length === 0;
  };

  // ── Step 1 submit ──
  const handleStep1 = () => {
    setAlert(null);
    if (!validate()) return;
    setLoading(true);
    setTimeout(() => {
      setLoading(false);
      setStep(2);
      startTimer();
    }, 1000);
  };

  // ── OTP verify ──
  const verifyOTP = () => {
    setAlert(null);
    if (otp.replace(/\D/g, "").length < 6) {
      setAlert({ type: "error", msg: "Please enter all 6 OTP digits." });
      return;
    }
    setLoading(true);
    setTimeout(() => {
      setLoading(false);
      setStep(3);
    }, 1200);
  };

  // ── Social ──
  const socialAuth = (p) => {
    console.log("Social auth:", p);
    setTimeout(() => { window.location.href = "/"; }, 1500);
  };

  // ── Step indicator ──
  const stepState = (n) => n < step ? "done" : n === step ? "active" : "pending";
  const steps = [
    { n: 1, label: "Details" },
    { n: 2, label: "Verify" },
    { n: 3, label: "Done" },
  ];

  return (
    <div style={S.page}>
      {/* ── Left panel ── */}
      <div style={S.left}>
        <div style={S.leftGlow} />
        <div style={S.leftInner}>
          <a href="/" style={S.logo}>The<span style={{ color: TOKEN.gold }}>Zuro</span></a>
          <div>
            <h2 style={S.tagline}>
              Join <span style={{ color: TOKEN.gold }}>TheZuro</span> — Shop Smarter
            </h2>
            <p style={S.taglineSub}>
              Start your journey with India's fastest-growing marketplace. Sign up free in 2 minutes.
            </p>
            <div style={S.features}>
              {[
                ["🎁", "₹200 welcome coupon on your first order"],
                ["🛍", "Access to 50,000+ products"],
                ["⚡", "Flash sale early access for members"],
                ["🔒", "Secure account with OTP verification"],
              ].map(([icon, text]) => (
                <div key={text} style={S.feat}>
                  <div style={S.featIcon}>{icon}</div>
                  <span>{text}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
        <div style={S.leftFoot}>© 2025 TheZuro. All rights reserved.</div>
      </div>

      {/* ── Right panel ── */}
      <div style={S.right}>
        <div style={S.box}>
          {/* Tabs */}
          <div style={S.tabs}>
            <button style={S.tab} onClick={() => (window.location.href = "/login")}>
              Sign In
            </button>
            <button style={S.tabActive}>Create Account</button>
          </div>

          {/* Step indicator */}
          {step < 3 && (
            <div style={S.stepRow}>
              {steps.map(({ n, label }, i) => (
                <>
                  <div key={n} style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
                    <div style={S.stepNum(stepState(n))}>
                      {stepState(n) === "done" ? "✓" : n}
                    </div>
                    <div style={S.stepLabel(stepState(n))}>{label}</div>
                  </div>
                  {i < steps.length - 1 && <div key={`line-${n}`} style={{ ...S.stepLine, marginBottom: "18px" }} />}
                </>
              ))}
            </div>
          )}

          {/* Alert */}
          {alert && <div style={S.alert(alert.type)}>{alert.type === "error" ? "⚠️" : "✅"} {alert.msg}</div>}

          {/* ── STEP 1: Details ── */}
          {step === 1 && (
            <>
              <h1 style={S.title}>Create Account ✨</h1>
              <p style={S.subtitle}>Join TheZuro — it's free forever</p>

              <div style={S.formRow2}>
                <FInput
                  label="First Name" required
                  placeholder="Rahul"
                  value={firstName}
                  onChange={setFirstName}
                  error={errors.firstName}
                />
                <FInput
                  label="Last Name" required
                  placeholder="Verma"
                  value={lastName}
                  onChange={setLastName}
                  error={errors.lastName}
                />
              </div>

              <FInput
                label="Email Address" required
                type="email" placeholder="you@example.com"
                value={email} onChange={setEmail}
                error={errors.email}
                autoComplete="email"
              />

              <PhoneInput value={phone} onChange={setPhone} error={errors.phone} />

              <FInput
                label="Password" required
                type={showPw ? "text" : "password"}
                placeholder="Create a strong password"
                value={password} onChange={setPassword}
                error={errors.password}
                hint={!errors.password ? "Min 8 chars, include a number & symbol" : undefined}
                autoComplete="new-password"
                rightSlot={
                  <button style={S.eyeBtn} type="button" onClick={() => setShowPw(!showPw)}>
                    {showPw ? "🙈" : "👁"}
                  </button>
                }
              />

              {/* Password strength */}
              {password && (
                <div style={{ marginTop: "-10px", marginBottom: "14px" }}>
                  <div style={S.strengthBar}>
                    {[1, 2, 3, 4].map((i) => (
                      <div key={i} style={S.strengthSeg(i <= strength.score, strength.color)} />
                    ))}
                  </div>
                  {strength.label && <div style={S.strengthLabel(strength.color)}>{strength.label} password</div>}
                </div>
              )}

              <FInput
                label="Confirm Password" required
                type={showCpw ? "text" : "password"}
                placeholder="Repeat your password"
                value={confirm} onChange={setConfirm}
                error={errors.confirm}
                autoComplete="new-password"
                rightSlot={
                  <button style={S.eyeBtn} type="button" onClick={() => setShowCpw(!showCpw)}>
                    {showCpw ? "🙈" : "👁"}
                  </button>
                }
              />

              {/* Terms */}
              <div style={S.termsRow}>
                <input
                  type="checkbox" id="terms"
                  checked={terms}
                  onChange={(e) => setTerms(e.target.checked)}
                  style={{ accentColor: TOKEN.gold, width: "16px", height: "16px", marginTop: "2px", flexShrink: 0 }}
                />
                <label htmlFor="terms" style={S.termsLabel}>
                  I agree to the{" "}
                  <a href="/terms" style={S.termsLink}>Terms of Service</a>{" "}
                  and{" "}
                  <a href="/privacy" style={S.termsLink}>Privacy Policy</a>
                  {errors.terms && <span style={{ color: TOKEN.red, display: "block", marginTop: "3px" }}>⚠ {errors.terms}</span>}
                </label>
              </div>

              <button
                style={{ ...S.submitBtn, opacity: loading ? 0.7 : 1, cursor: loading ? "not-allowed" : "pointer" }}
                onClick={handleStep1}
                disabled={loading}
              >
                {loading ? "⏳ Creating account…" : "Continue →"}
              </button>

              <div style={S.divider}>
                <div style={S.divLine} /> or sign up with <div style={S.divLine} />
              </div>
              <div style={S.social}>
                <button style={S.socialBtn} onClick={() => socialAuth("Google")}>
                  <span style={{ fontSize: "18px" }}>G</span> Google
                </button>
                <button style={S.socialBtn} onClick={() => socialAuth("Facebook")}>
                  <span style={{ fontSize: "18px" }}>📘</span> Facebook
                </button>
              </div>
              <p style={S.footerTxt}>
                Already have an account?{" "}
                <a href="/login" style={S.footerLink}>Sign in</a>
              </p>
            </>
          )}

          {/* ── STEP 2: OTP verify ── */}
          {step === 2 && (
            <>
              <button style={S.backBtn} onClick={() => { setStep(1); setOtp(""); setAlert(null); }}>
                ← Back
              </button>
              <h1 style={S.title}>Verify Phone 📱</h1>
              <p style={S.subtitle}>
                Enter the 6-digit OTP sent to{" "}
                <strong style={{ color: TOKEN.black }}>+91 {phone}</strong>
              </p>

              <OTPInput id="reg-otp" value={otp} onChange={setOtp} />

              <button
                style={{ ...S.submitBtn, opacity: loading ? 0.7 : 1, cursor: loading ? "not-allowed" : "pointer" }}
                onClick={verifyOTP}
                disabled={loading}
              >
                {loading ? "⏳ Verifying…" : "Verify & Create Account →"}
              </button>

              <p style={S.resend}>
                Didn't receive?{" "}
                {otpTimer > 0 ? (
                  <span style={{ color: TOKEN.gray400 }}>Resend in {otpTimer}s</span>
                ) : (
                  <span style={S.resendLink} onClick={() => { setOtp(""); startTimer(); }}>
                    Resend OTP
                  </span>
                )}
              </p>

              <div style={{ ...S.hint, textAlign: "center", marginTop: "12px" }}>
                Wrong number?{" "}
                <span
                  style={{ color: TOKEN.gold, cursor: "pointer", fontWeight: 500 }}
                  onClick={() => setStep(1)}
                >
                  Edit phone number
                </span>
              </div>
            </>
          )}

          {/* ── STEP 3: Success ── */}
          {step === 3 && (
            <div style={S.successWrap}>
              <div style={S.successIcon}>🎉</div>
              <h2 style={S.successTitle}>Account Created!</h2>
              <p style={S.successDesc}>
                Welcome to TheZuro, {firstName}! Your account is ready.<br />
                Use code <strong style={{ color: TOKEN.gold }}>WELCOME200</strong> on your first order.
              </p>
              <a href="/" style={S.successBtn}>Start Shopping →</a>
              <p style={{ ...S.hint, marginTop: "16px" }}>
                A confirmation email has been sent to{" "}
                <strong>{email}</strong>
              </p>
            </div>
          )}
        </div>
      </div>

      {/* ── Fonts + responsive ── */}
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=DM+Sans:wght@400;500;600&family=DM+Mono:wght@500&display=swap');
        * { box-sizing: border-box; }
        @media (max-width: 900px) {
          .reg-left { display: none !important; }
          .reg-right { width: 100% !important; }
        }
        button { transition: opacity .2s; }
        button:hover { opacity: 0.88; }
        input[type="checkbox"] { cursor: pointer; }
      `}</style>
    </div>
  );
}
